PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('manager','employee')), rate INTEGER NOT NULL CHECK(rate >= 0), password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lots(id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, product TEXT NOT NULL, unit TEXT NOT NULL, price INTEGER NOT NULL CHECK(price >= 0), opening INTEGER NOT NULL CHECK(opening >= 0), start_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), date TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes > 0), rate INTEGER NOT NULL, timed TEXT NOT NULL, pieces TEXT NOT NULL, amount INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(user_id,date));
CREATE INDEX IF NOT EXISTS idx_reports_date ON reports(date);
CREATE TABLE IF NOT EXISTS shipments(id INTEGER PRIMARY KEY AUTOINCREMENT, lot_id INTEGER NOT NULL REFERENCES lots(id), date TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0), memo TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_shipments_lot_date ON shipments(lot_id,date);
CREATE TABLE IF NOT EXISTS counts(lot_id INTEGER NOT NULL REFERENCES lots(id), date TEXT NOT NULL, actual INTEGER NOT NULL CHECK(actual >= 0), signature TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), PRIMARY KEY(lot_id,date));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, at TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_limits(key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, product TEXT NOT NULL, unit TEXT NOT NULL DEFAULT '盒', stage TEXT NOT NULL DEFAULT 'finished' CHECK(stage IN ('finished','semi')), price INTEGER NOT NULL CHECK(price>=0), start_date TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, UNIQUE(product,unit));
CREATE TABLE IF NOT EXISTS legacy_products(lot_id INTEGER PRIMARY KEY REFERENCES lots(id), product_id INTEGER NOT NULL REFERENCES products(id));
CREATE TABLE IF NOT EXISTS intake_counts(product_id INTEGER NOT NULL REFERENCES products(id), date TEXT NOT NULL, actual INTEGER NOT NULL CHECK(actual>=0), actor INTEGER NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL, signature TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(product_id,date));

CREATE TABLE IF NOT EXISTS direct_sales(product_id INTEGER NOT NULL REFERENCES products(id), date TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>=0), memo TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(product_id,date));

CREATE TABLE IF NOT EXISTS process_links(id INTEGER PRIMARY KEY, source_id INTEGER NOT NULL UNIQUE REFERENCES products(id), target_id INTEGER NOT NULL UNIQUE REFERENCES products(id), start_date TEXT NOT NULL, CHECK(source_id != target_id));
